func TestCategoricalReportedLossInvalid148(t *testing.T) {
	cases := []struct {
		name   string
		logits []float64
		target int
		factor float64
	}{
		{"empty", nil, 0, 1}, {"negative_target", []float64{0}, -1, 1}, {"large_target", []float64{0}, 1, 1},
		{"nan_score", []float64{math.NaN()}, 0, 1}, {"positive_inf_score", []float64{math.Inf(1)}, 0, 1}, {"negative_inf_score", []float64{math.Inf(-1)}, 0, 1},
		{"negative_factor", []float64{0}, 0, -1}, {"nan_factor", []float64{0}, 0, math.NaN()}, {"infinite_factor", []float64{0}, 0, math.Inf(1)},
		{"zero_factor_does_not_hide_invalid_score", []float64{math.NaN()}, 0, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			before := make([]uint64, len(tc.logits))
			for i, v := range tc.logits {
				before[i] = math.Float64bits(v)
			}
			got, err := Loss(tc.logits, tc.target, tc.factor)
			if err == nil || math.Float64bits(got) != 0 {
				t.Fatalf("invalid input: loss %g, error %v; want zero and error", got, err)
			}
			for i, b := range before {
				if math.Float64bits(tc.logits[i]) != b {
					t.Errorf("input %d mutated", i)
				}
			}
		})
	}
}
